/// The one GPUI entity that owns the editor model. Everything on screen is a function of this.
pub struct App { pub workspace: kate_core::Workspace }

/// GPUI element that paints one View of one Document. Holds only layout caches, never model state.
pub struct EditorElement { view: kate_core::ViewId, line_height: gpui::Pixels, glyph_cache: ShapedLineCache }

/// Shaped text per visible logical line, keyed by (line index, buffer revision, theme revision).
pub struct ShapedLineCache { lines: std::collections::HashMap<(u32, kate_text::Revision), gpui::ShapedLine> }

/// Frame-time telemetry written to stderr as JSON lines when KATEM5_PROFILE=1. This is the spike's deliverable.
#[derive(serde::Serialize)]
pub struct FrameSample { pub frame: u64, pub paint_micros: u64, pub first_line: u32, pub lines_painted: u32 }

pub fn run(path: Option<std::path::PathBuf>) -> !; // opens the window, blocks until quit

[workspace.dependencies]
kate-ui = { path = "crates/kate-ui" }
# apps/katem5rust/Cargo.toml: kate-ui = { workspace = true }
